INSERT INTO listings (id, title, slug, status, price, deposit, address_line_1, city, state, zip, neighborhood, bedrooms, bathrooms, square_feet, parking, pets_allowed, furnished, available_date, lease_terms, description, amenities, featured) VALUES
('a1b2c3d4-e5f6-7890-abcd-ef1234567890', 'Stunning Oceanview 2BR Apartment', 'stunning-oceanview-2br-apartment', 'available', 2850, 2850, '245 Coastal Boulevard, Unit 4B', 'Coastal City', 'CA', '90210', 'Harbor Heights', 2, 2, 1150, '1 covered garage spot', true, false, '2025-07-01', '12 months preferred', 'Wake up to breathtaking ocean views in this beautifully updated 2-bedroom apartment in Harbor Heights. Open-concept living, modern kitchen with quartz countertops, in-unit washer/dryer, and private balcony.', ARRAY['Central A/C','In-Unit W/D','Dishwasher','Balcony','Pool','Fitness Center','Concierge'], true),
('b2c3d4e5-f6a7-8901-bcde-f12345678901', 'Modern Downtown Loft with City Views', 'modern-downtown-loft-city-views', 'available', 3200, 3200, '88 Main Street, Loft 12', 'Coastal City', 'CA', '90211', 'Downtown', 1, 1, 950, '1 underground spot', false, false, '2025-06-15', '12 months', 'Sleek industrial-chic loft with 14-foot ceilings, exposed brick, and massive windows. Chef kitchen with professional appliances. Steps from restaurants and the harbor waterfront.', ARRAY['Central A/C','Exposed Brick','High Ceilings','Dishwasher','Hardwood Floors','Rooftop Access'], true),
('c3d4e5f6-a7b8-9012-cdef-123456789012', 'Charming 3BR Family Home with Garden', 'charming-3br-family-home-garden', 'available', 3500, 5000, '1247 Maple Lane', 'Coastal City', 'CA', '90212', 'Maplewood', 3, 2, 1800, '2-car garage', true, false, '2025-08-01', '12 months minimum', 'Beautifully maintained family home with three bedrooms, open kitchen, living room with fireplace, and private backyard with garden and covered patio. Walking distance to top-rated schools.', ARRAY['Garage','Backyard','Fireplace','Dishwasher','Central A/C','W/D Hookups','Storage Shed'], true),
('d4e5f6a7-b8c9-0123-defa-234567890123', 'Cozy Furnished Studio Near the Beach', 'cozy-furnished-studio-near-beach', 'available', 1650, 1650, '502 Shoreline Drive, Unit 1A', 'Coastal City', 'CA', '90210', 'Shoreline District', 0, 1, 480, 'Street parking', false, true, '2025-06-01', '6 or 12 months', 'Fully furnished studio two blocks from the beach! Murphy bed, built-in shelving, kitchenette. Communal courtyard with BBQ. Utilities included. Ideal for young professionals.', ARRAY['Furnished','Utilities Included','Courtyard','BBQ Area','Laundry On-Site'], false),
('e5f6a7b8-c9d0-1234-efab-345678901234', 'Luxury Penthouse with Panoramic Views', 'luxury-penthouse-panoramic-views', 'available', 6500, 10000, '1 Harbor Tower, PH-1', 'Coastal City', 'CA', '90210', 'Harbor Heights', 3, 3, 2800, '2 reserved spots', true, false, '2025-09-01', '12 months', 'Crown jewel of Harbor Tower with 270-degree ocean/city views. Three bedrooms, spa-like primary bath, gourmet kitchen with wine fridge, wraparound private terrace. Full concierge services.', ARRAY['Concierge','Rooftop Pool','Spa','Wine Fridge','Smart Home','Private Terrace','Fitness Center'], true),
('f6a7b8c9-d0e1-2345-fabc-456789012345', 'Recently Renovated 2BR Townhouse', 'recently-renovated-2br-townhouse', 'available', 2400, 2400, '39 Cedar Court', 'Coastal City', 'CA', '90213', 'Cedar Park', 2, 1.5, 1200, '1 assigned spot', true, false, '2025-07-15', '12 months', 'Freshly renovated townhouse with new flooring, updated kitchen and bathrooms. Two bedrooms, private patio. Community pool and playground. Near hiking trails.', ARRAY['Patio','Community Pool','Playground','New Appliances','Central A/C','In-Unit W/D'], false),
('a7b8c9d0-e1f2-3456-abcd-567890123456', 'Bright 1BR in Historic Harborside', 'bright-1br-historic-harborside', 'available', 1950, 1950, '712 Harbor Way, Apt 3', 'Coastal City', 'CA', '90210', 'Harborside', 1, 1, 720, 'Street parking', true, false, '2025-06-01', '12 months', 'Charming one-bedroom in a restored historic building. Original hardwood floors, crown molding, updated kitchen and bath. Walk to farmer''s market and marina.', ARRAY['Hardwood Floors','Crown Molding','Updated Kitchen','Pet-Friendly','Walk to Marina'], false),
('b8c9d0e1-f2a3-4567-bcde-678901234567', 'Spacious 2BR with Mountain Views', 'spacious-2br-mountain-views', 'rented', 2200, 2200, '850 Ridgeline Road, Unit 6', 'Coastal City', 'CA', '90214', 'Ridge Valley', 2, 1, 1050, '1 carport spot', false, false, NULL, '12 months', 'Sweeping mountain views from this spacious two-bedroom. Open floor plan, updated kitchen, private balcony. Pool, tennis, dog run. Minutes from hiking trails.', ARRAY['Balcony','Pool','Tennis','Dog Run','Mountain Views','Carport'], false),
('c9d0e1f2-a3b4-5678-cdef-789012345678', 'Garden-Level 1BR with Private Entrance', 'garden-level-1br-private-entrance', 'pending', 1800, 1800, '445 Willow Street, Unit G', 'Coastal City', 'CA', '90212', 'Maplewood', 1, 1, 650, 'Driveway parking', true, false, '2025-07-01', '12 months', 'Unique garden-level apartment with private entrance and small front garden. Updated finishes. Quiet residential street in Maplewood.', ARRAY['Private Entrance','Garden','Quiet Street','Pet-Friendly','Updated Finishes'], false),
('d0e1f2a3-b4c5-6789-defa-890123456789', 'New Construction 4BR Waterfront Home', 'new-construction-4br-waterfront', 'draft', 7200, 10000, '2 Lighthouse Point', 'Coastal City', 'CA', '90210', 'Lighthouse Point', 4, 3.5, 3200, '3-car garage', true, false, '2025-10-01', '12-24 months', 'Brand-new waterfront home with four bedrooms, gourmet kitchen, home office, and three-car garage. Smart home technology. Private dock access available.', ARRAY['Waterfront','Smart Home','Home Office','Gourmet Kitchen','Dock Access','Three-Car Garage'], false);
